// UI texts. The German dictionary is the source; every other one is typed as `Dictionary`, so a
// missing or unknown key is a type error. Placeholders: `{name}`, identical in all languages
// (checked by i18n.test.ts).
//
// Plural forms: a text with a number exists once per plural category of the language, as the base
// key plus `.zero`, `.one`, `.two`, `.few`, `.many` or `.other`. The caller passes the base key and
// the number (`{count}`, or `{days}` in texts about days); `Intl.PluralRules` picks the form. Every
// language has exactly the categories its plural rules report, `.other` always (i18n.test.ts).
//
// The languages, their order and the form of address are the same as in Hangar: informal "you"
// wherever software in that language uses it (de, en, es, fr, el, it, pl, pt, ru, tr), otherwise a
// neutral imperative. Japanese and Chinese stay neutrally polite and avoid direct address where
// possible. Portuguese means Brazilian Portuguese (pt-BR).

import { createContext, useContext } from "react";

export type Language =
  "de" | "en" | "el" | "es" | "fr" | "it" | "ja" | "pl" | "pt" | "ru" | "tr" | "zh";

/**
 * Order of the picker: German and English first (source and fallback language), then by
 * language code. Codes sort independently of the script; sorting by native names would have to
 * order Latin, Greek, Cyrillic and CJK scripts against each other and would look random.
 */
export const LANGUAGES: readonly Language[] = [
  "de",
  "en",
  "el",
  "es",
  "fr",
  "it",
  "ja",
  "pl",
  "pt",
  "ru",
  "tr",
  "zh",
];

/** The tag handed to `Intl`: Portuguese is Brazilian, Chinese is Simplified. */
export const LOCALES: Record<Language, string> = {
  de: "de-DE",
  en: "en-US",
  el: "el-GR",
  es: "es-ES",
  fr: "fr-FR",
  it: "it-IT",
  ja: "ja-JP",
  pl: "pl-PL",
  pt: "pt-BR",
  ru: "ru-RU",
  tr: "tr-TR",
  zh: "zh-CN",
};

