// @i18n-source-end

type SourceKey = keyof typeof de;

export const PLURAL_CATEGORIES = ["zero", "one", "two", "few", "many", "other"] as const;
export type PluralCategory = (typeof PLURAL_CATEGORIES)[number];

type BaseOf<K> = K extends `${infer Base}.other` ? Base : never;
/** Base keys of texts with plural forms, such as `names.banner`. */
export type PluralKey = BaseOf<SourceKey>;
export type PluralFormKey = `${PluralKey}.${PluralCategory}`;
/** Keys of texts without a number. */
export type TextKey = Exclude<SourceKey, PluralFormKey>;
/** What callers pass to `t`: a plain key or the base of a plural text. */
export type MessageKey = TextKey | PluralKey;

/** One language: every plain text, `.other` of every plural text, the other forms it needs. */
export type Dictionary = Readonly<
  Record<TextKey, string> &
    Record<`${PluralKey}.other`, string> &
    Partial<Record<PluralFormKey, string>>
>;

