// @i18n-translations-end

export const DICTIONARIES: Record<Language, Dictionary> = {
  de,
  en,
  el,
  es,
  fr,
  it,
  ja,
  pl,
  pt,
  ru,
  tr,
  zh,
};

/**
 * Native names of the languages, each in its own language and the same in every UI (so you can
 * find your own language).
 */
export const LANGUAGE_NAMES: Record<Language, string> = {
  de: "Deutsch",
  en: "English",
  el: "Ελληνικά",
  es: "Español",
  fr: "Français",
  it: "Italiano",
  ja: "日本語",
  pl: "Polski",
  pt: "Português",
  ru: "Русский",
  tr: "Türkçe",
  zh: "简体中文",
};

export type Params = Readonly<Record<string, string | number>>;
export type Translate = (key: MessageKey, params?: Params) => string;

const PLURAL_BASES: ReadonlySet<string> = new Set(
  Object.keys(de)
    .filter((key) => key.endsWith(".other"))
    .map((key) => key.slice(0, -".other".length)),
);

export function isPluralKey(key: string): key is PluralKey {
  return PLURAL_BASES.has(key);
}

/** All plural base keys, for the completeness test. */
export function pluralKeys(): PluralKey[] {
  return Object.keys(de).filter(isPluralKey);
}

/** All plain keys, for the completeness test. */
export function textKeys(): TextKey[] {
  const forms = new Set<string>();
  for (const base of PLURAL_BASES) {
    for (const category of PLURAL_CATEGORIES) forms.add(`${base}.${category}`);
  }
  return Object.keys(de).filter((key): key is TextKey => !forms.has(key) && key in de);
}

const pluralRulesCache = new Map<Language, Intl.PluralRules>();
const numberFormatCache = new Map<Language, Intl.NumberFormat>();

export function pluralRules(language: Language): Intl.PluralRules {
  let rules = pluralRulesCache.get(language);
  if (!rules) {
    rules = new Intl.PluralRules(LOCALES[language]);
    pluralRulesCache.set(language, rules);
  }
  return rules;
}

function numberFormat(language: Language): Intl.NumberFormat {
  let format = numberFormatCache.get(language);
  if (!format) {
    format = new Intl.NumberFormat(LOCALES[language]);
    numberFormatCache.set(language, format);
  }
  return format;
}

function formKey(key: PluralKey, category: PluralCategory): PluralFormKey {
  return `${key}.${category}`;
}

/** The number that picks the plural form: `{count}`, else `{days}`. */
function pluralNumber(params: Params | undefined): number {
  const value = params?.count ?? params?.days;
  return typeof value === "number" ? value : 0;
}

function lookup(language: Language, key: MessageKey, params: Params | undefined): string {
  const dictionary = DICTIONARIES[language];
  if (!isPluralKey(key)) return dictionary[key];
  const category = pluralRules(language).select(pluralNumber(params));
  // A missing form falls back to `.other` of the language (the test makes sure it never does).
  return dictionary[formKey(key, category)] ?? dictionary[`${key}.other`];
}

/**
 * Right-to-left letters and the bidi control characters (marks, embeddings, overrides, isolates).
 * A value with one of them could reorder the sentence around it.
 */
const BIDI_RELEVANT = /[֐-ࣿ‎‏؜‪-‮⁦-⁩יִ-﷿ﹰ-ﻼ]/u;
const FIRST_STRONG_ISOLATE = String.fromCharCode(0x2068);
const POP_DIRECTIONAL_ISOLATE = String.fromCharCode(0x2069);

/**
 * A file, folder or device name inside a sentence, isolated so that right-to-left letters or
 * bidi controls in it cannot reorder or spoof the text around it (Unicode UAX #9, FSI ... PDI).
 * All twelve UI languages run left to right, so a value without such characters looks the same
 * with or without the isolate; it is added only where it can matter, which keeps plain texts
 * plain for tests and the tray.
 */
export function isolateName(value: string): string {
  return BIDI_RELEVANT.test(value)
    ? `${FIRST_STRONG_ISOLATE}${value}${POP_DIRECTIONAL_ISOLATE}`
    : value;
}

export function translate(language: Language, key: MessageKey, params?: Params): string {
  const text = lookup(language, key, params);
  if (!params) return text;
  return text.replace(/\{(\w+)\}/g, (match, name: string) => {
    const value = params[name];
    if (value === undefined) return match;
    return typeof value === "number" ? numberFormat(language).format(value) : isolateName(value);
  });
}

export function createTranslator(language: Language): Translate {
  return (key, params) => translate(language, key, params);
}

/**
 * Language from a BCP 47 tag such as `de-AT`, `pt-BR` or `zh-Hant-TW`: only the primary
 * subtag before `-` or `_` matters. Chinese in any variant maps to Simplified Chinese because
 * there is no Traditional translation; unknown languages map to English.
 */
export function detectLanguage(tag: string | undefined): Language {
  const primary = tag?.trim().toLowerCase().split(/[-_]/)[0];
  return LANGUAGES.find((language) => language === primary) ?? "en";
}

export function isLanguage(value: unknown): value is Language {
  return LANGUAGES.some((language) => language === value);
}

/** Placeholder names of a text, sorted (for the completeness check). */
export function placeholders(text: string): string[] {
  return Array.from(text.matchAll(/\{(\w+)\}/g), (m) => m[1] ?? "").sort();
}

export interface I18n {
  readonly language: Language;
  readonly t: Translate;
}

export function createI18n(language: Language): I18n {
  return { language, t: createTranslator(language) };
}

export const I18nContext = createContext<I18n>(createI18n("en"));

export function useT(): Translate {
  return useContext(I18nContext).t;
}

export function useLanguage(): Language {
  return useContext(I18nContext).language;
}
